def decrypt(encrypted_text: str, n: int) -> str:
    if encrypted_text is None or encrypted_text == '' or n <= 0:
        return encrypted_text
    if n == 0:
        return encrypted_text
    for _ in range(n):
        even_chars = encrypted_text[1::2]
        odd_chars = encrypted_text[::2]
        encrypted_text = odd_chars + even_chars
    return encrypted_text
